import { render, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { describe, expect, it, vi } from "vitest";
import LoginForm from "../components/LoginForm";

function renderComponent(
  onSubmit = vi.fn<() => Promise<void>>().mockResolvedValue(undefined)
) {
  const user = userEvent.setup();

  render(<LoginForm onSubmit={onSubmit} />);

  return {
    user,
    onSubmit,
    getEmailInput: () => screen.getByRole("textbox", { name: /email/i }),
    getPasswordInput: () => screen.getByLabelText(/password/i),
    getSubmitButton: () => screen.getByRole("button", { name: /login/i })
  };
}

describe("LoginForm", () => {
  // TICKET 1.1
  it.todo("renders email, password and login button");

  // TICKET 1.2
  it.todo("keeps the submit button enabled initially");

  // TICKET 1.3
  it.todo("shows a validation message and does not submit when fields are empty");

  // TICKET 1.4
  it.todo("submits trimmed credentials when the form is valid");

  // TICKET 1.5
  it.todo("disables inputs and button while the async submission is pending");

  // TICKET 1.6
  it.todo("enables the form again after a successful submission");

  // TICKET 1.7
  it.todo("shows an error and enables the form again when submission fails");
});
